// One-off migration of <app-pill> v1 usages to the v2 API. Usage: node migrate.js <srcRoot>
const fs = require("fs"), path = require("path");
const root = process.argv[2];
const TONE = { info: "neutral", success: "positive", warning: "caution" };
const errors = [];
const changed = new Map(); // file -> Set of owner ts files needing pipe

function walk(d, out = []) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p, out);
    else if (/\.(html|ts)$/.test(e.name) && !/\.spec\.ts$/.test(e.name)) out.push(p);
  }
  return out;
}

// Returns the expression with a leading `!` removed or added, minimally.
function negate(e) {
  e = e.trim();
  if (e === "true") return "false";
  if (e === "false") return "true";
  if (e.startsWith("!(") && e.endsWith(")")) {
    let depth = 0, closesAtEnd = false;
    for (let i = 1; i < e.length; i++) {
      if (e[i] === "(") depth++;
      else if (e[i] === ")" && --depth === 0) { closesAtEnd = i === e.length - 1; break; }
    }
    if (closesAtEnd) return e.slice(2, -1);
  }
  if (/^![\w$.?\[\]'()]+$/.test(e)) return e.slice(1);
  if (/^[\w$.?\[\]'()]+$/.test(e)) return "!" + e;
  return "!(" + e + ")";
}

// Maps a bound [variant] expression. Literal values and ternaries whose branches are all
// literals are mapped in place; anything else goes through the pillTone pipe.
function mapVariant(e) {
  const t = e.trim();
  const lits = [...t.matchAll(/'([^']*)'/g)].map(m => m[1]);
  if (/^'[^']*'$/.test(t) && TONE[lits[0]]) return { expr: `'${TONE[lits[0]]}'`, pipe: false };
  if (t.includes("?") && lits.length && lits.every(l => TONE[l])) {
    return { expr: t.replace(/'([^']*)'/g, (_, l) => `'${TONE[l]}'`), pipe: false };
  }
  return { expr: `${t} | pillTone`, pipe: true };
}

function findOwnerTs(file) {
  if (file.endsWith(".ts")) return file;
  const dir = path.dirname(file), base = path.basename(file);
  const owners = fs.readdirSync(dir).filter(f => f.endsWith(".ts") && !f.endsWith(".spec.ts"))
    .map(f => path.join(dir, f)).filter(f => fs.readFileSync(f, "utf8").includes(`"./${base}"`));
  if (owners.length !== 1) { errors.push(`${file}: owner ts not unique`); return null; }
  return owners[0];
